import { Router } from "express";
import { getHero, createHero, updateHero, deleteHero, } from "../controllers/hero.controller.js";
import { validateRequest } from "../../../middlewares/validators.middleware.js";
import { verifyAuth } from "../../../middlewares/verifyAuth.middleware.js";
import { verifyAdmin } from "../../../middlewares/verifyAdmin.middleware.js";
import { validateCreateHero, validateUpdateHero, } from "../validators/hero.validators.js";
const router = Router();
router.get("/", getHero);
router.post("/", verifyAuth, verifyAdmin, validateRequest(validateCreateHero), createHero);
router.put("/", verifyAuth, verifyAdmin, validateRequest(validateUpdateHero), updateHero);
router.delete("/", verifyAuth, verifyAdmin, deleteHero);
export default router;
